"use client";

/**
 * Keeps a phone or tablet screen from auto-locking while something long runs
 * (a lesson video upload). Two layers:
 *  1. The Screen Wake Lock API, re-requested every time the page comes back,
 *     because the browser drops it whenever the page is hidden.
 *  2. On iPhone and iPad, a tiny silent video playing on a loop out of sight.
 *     Home-screen apps on iOS before 18.4 (David's iPad is on 16.7) accept the
 *     wake lock request but ignore it; a playing video keeps them awake.
 * The video has to be started once from a tap, so call primeKeepAwake() in a
 * click handler (e.g. "Choose lesson video") before the long job begins.
 */

const SILENT_MP4 = "data:video/mp4;base64,";

let holders = 0;
let lock: WakeLockSentinel | null = null;
let video: HTMLVideoElement | null = null;
let listening = false;

function isApple(): boolean {
  if (typeof navigator === "undefined") return false;
  return /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
}

function getVideo(): HTMLVideoElement {
  if (video) return video;
  const v = document.createElement("video");
  v.src = SILENT_MP4;
  v.muted = true;
  v.loop = true;
  v.playsInline = true;
  v.setAttribute("muted", "");
  v.setAttribute("playsinline", "");
  v.setAttribute("aria-hidden", "true");
  v.style.cssText = "position:fixed;left:0;bottom:0;width:1px;height:1px;opacity:0.01;pointer-events:none;z-index:-1";
  document.body.appendChild(v);
  video = v;
  return v;
}

async function requestLock() {
  if (lock && !lock.released) return;
  try {
    lock = (await navigator.wakeLock?.request("screen")) ?? null;
  } catch {
    lock = null;
  }
}

function apply() {
  if (holders <= 0 || document.visibilityState !== "visible") return;
  void requestLock();
  if (isApple() || !("wakeLock" in navigator)) getVideo().play().catch(() => {});
}

function onVisible() {
  apply();
}

/** Call from a tap so the iOS fallback video is allowed to play later. */
export function primeKeepAwake() {
  if (typeof document === "undefined") return;
  if (!isApple() && "wakeLock" in navigator) return;
  const v = getVideo();
  v.play()
    .then(() => {
      if (holders <= 0) v.pause();
    })
    .catch(() => {});
}

/** Holds the screen awake until the returned release() is called. */
export function keepAwake(): () => void {
  if (typeof document === "undefined") return () => {};
  holders++;
  if (!listening) {
    document.addEventListener("visibilitychange", onVisible);
    listening = true;
  }
  apply();
  let released = false;
  return () => {
    if (released) return;
    released = true;
    holders = Math.max(0, holders - 1);
    if (holders > 0) return;
    lock?.release().catch(() => {});
    lock = null;
    video?.pause();
  };
}
